mapper.select:
/* Attd11Mapper.selectAttdSummaryRows */ WITH RECURSIVE /* 1. 부서 트리 — 시작 노드부터 하위까지 (nodeCd 미지정 시 사업장 전체) */ node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
/* 2. 대상 사용자 (USE_YN='Y', 미퇴사) */ target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD , U.USER_ID , U.USER_NM , U.NODE_CD , U.AUTH_CD , NT.NODE_NM FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
)
/* 3. 메인 — 출퇴근 실적(차수 행) + 차수별 유효 스케줄 결합 */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.NODE_NM AS deptNm , U.AUTH_CD AS authCd , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'BAIM_VAL', U.AUTH_CD, 'COM005') AS authNm
, A.WORK_YMD AS workYmd , A.WORK_SEQ AS workSeq
/* 차수에 맞춰 정규화한 스케줄 계획시각/휴게 (1구간/2구간) */ , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_STR_TIME ELSE SCH.FST_SCH_STR_TIME END AS planStart , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_END_TIME ELSE SCH.FST_SCH_END_TIME END AS planEnd , CASE WHEN A.WORK_SEQ = 2 THEN SCH.SEC_SCH_BRK_MIN ELSE SCH.FST_SCH_BRK_MIN END AS planBreakMin
/* 실제(원본) 출퇴근 일시 — 표준화 아님 */ , A.CHECK_IN_DATE AS actInDate , A.CHECK_IN_TIME AS actInTime , A.CHECK_OUT_DATE AS actOutDate , A.CHECK_OUT_TIME AS actOutTime
/* PRAFTA-FIXEDOT-3: 스케줄 원시 시각 + 고정연장(전방·후방) + 연차 계열 면제 존재. 지각/조퇴/근무시간 판정·집계식은 불변 — 아래 컬럼은 "고정연장 실적(자동 계상)" 합산과 "연장 미이행" 월 카운트(정책 ② — 조퇴 통계와 분리) 전용이다(additive). fixedOtExemptYn = 그날 종일('00' 기간 포함)/부분(01~04 당일) 확정 연차 존재(정책 ③). ⚠️ record(AttdSummaryRowResult) 끝 9필드와 동일 순서(위치 기반 매핑). */ , SCH.FST_SCH_STR_TIME AS fstSchStrTime , SCH.FST_SCH_END_TIME AS fstSchEndTime , SCH.SEC_SCH_STR_TIME AS secSchStrTime , SCH.SEC_SCH_END_TIME AS secSchEndTime , SCH.PRE_FIXED_OT_STR_TIME AS preFixedOtStrTime , SCH.PRE_FIXED_OT_END_TIME AS preFixedOtEndTime , SCH.FIXED_OT_STR_TIME AS fixedOtStrTime , SCH.FIXED_OT_END_TIME AS fixedOtEndTime , CASE WHEN EXISTS ( SELECT 1 FROM TB_USER_LEAVE_USE LX WHERE LX.CMPNY_CD = A.CMPNY_CD AND LX.USER_CD = A.USER_CD AND LX.LEAVE_STATUS = 'CONFIRMED' AND LX.DEL_YN = 'N' AND ( ( LX.USE_UNIT_TYPE = '00' AND LX.START_DATE <= A.WORK_YMD AND LX.END_DATE >= A.WORK_YMD ) OR ( LX.USE_UNIT_TYPE <> '00' AND LX.START_DATE = A.WORK_YMD ) ) ) THEN 'Y' ELSE 'N' END AS fixedOtExemptYn
/* (삭제) 그날 확정 반차 면제 구간 MIN 스칼라 서브쿼리 — 2026-08-07 D-3. "반차는 하루 1건"을 전제했으나 실제로는 하루 2건(시작기준 0.5 + 종료기준 0.5 = 1.0)이 성립해 MIN 이 0900 + 1300 을 섞어 종일 쉰 사람에게 지각·조퇴가 떴다. → 면제 구간은 selectHalfLeaveWindows 로 행 그대로 읽고, 합집합 판정은 서비스 (PartialLeaveWindowUtils.resolveAll)가 한다. */
FROM target_user U INNER JOIN TB_USER_ATTD_MGMT A ON A.CMPNY_CD = U.CMPNY_CD AND A.SITE_CD = U.SITE_CD AND A.USER_CD = U.USER_CD AND A.WORK_SEQ IN (1, 2) AND A.DEL_YN = 'N' AND A.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%')
LEFT JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = A.CMPNY_CD AND WP.SITE_CD = A.SITE_CD AND WP.USER_CD = A.USER_CD AND WP.WORK_YMD = A.WORK_YMD
/* 근무계획코드가 스케줄코드인 경우 — 근무일(A.WORK_YMD) 기준 유효 스케줄(effective-dating). TB_SCH_MGMT(현재본) + TB_SCH_MGMT_HIST(전 버전) UNION 후 APPLY_DATE <= WORK_YMD 인 가장 최근 버전의 시간값을 결합한다. (attd07 selectMonthlyAttdList 의 SCH 서브쿼리 그대로 재사용) USE_YN 필터 없음: 사용중지된 근무타입이 배정된 날도 그날 스케줄 시각으로 집계/판정해야 한다. */ LEFT JOIN ( SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME , E.SEC_SCH_BRK_MIN , E.PRE_FIXED_OT_STR_TIME , E.PRE_FIXED_OT_END_TIME , E.FIXED_OT_STR_TIME , E.FIXED_OT_END_TIME FROM ( SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.FST_SCH_STR_TIME , M.FST_SCH_END_TIME , M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME , M.SEC_SCH_END_TIME , M.SEC_SCH_BRK_MIN , M.PRE_FIXED_OT_STR_TIME , M.PRE_FIXED_OT_END_TIME , M.FIXED_OT_STR_TIME , M.FIXED_OT_END_TIME , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M
UNION ALL
SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.FST_SCH_STR_TIME , H.FST_SCH_END_TIME , H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME , H.SEC_SCH_END_TIME , H.SEC_SCH_BRK_MIN , H.PRE_FIXED_OT_STR_TIME , H.PRE_FIXED_OT_END_TIME , H.FIXED_OT_STR_TIME , H.FIXED_OT_END_TIME , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD
AND SCH.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD )
ORDER BY U.USER_CD, A.WORK_YMD, A.WORK_SEQ

/* Attd11Mapper.selectOvertimeSummary */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD , U.USER_ID , U.USER_NM , U.AUTH_CD , NT.NODE_NM FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
)
/* OT-only(정규 출근기록 없는 휴일 초과근무 등) 사용자도 1행으로 노출하기 위해 사용자 기본정보(userId/userNm/deptNm/authCd/authNm)를 함께 내려준다. */ SELECT O.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.NODE_NM AS deptNm , U.AUTH_CD AS authCd , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'BAIM_VAL', U.AUTH_CD, 'COM005') AS authNm , IFNULL(SUM(O.WORK_MINUTES), 0) AS otMinutes FROM TB_USER_OVERTIME_MGMT O INNER JOIN target_user U ON O.CMPNY_CD = U.CMPNY_CD AND O.SITE_CD = U.SITE_CD AND O.USER_CD = U.USER_CD WHERE O.CMPNY_CD = #{gvCmpnyCd} AND O.SITE_CD = #{siteCd} AND O.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%') AND O.DEL_YN = 'N' AND O.OT_STATUS = 'COMPLETED' GROUP BY O.USER_CD, U.CMPNY_CD, U.USER_ID, U.USER_NM, U.NODE_NM, U.AUTH_CD

/* Attd11Mapper.selectAbsentDayRows */ WITH RECURSIVE node_tree AS ( SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd}
AND N.NODE_CD = #{nodeCd}
AND N.PARENT_NODE_CD IS NULL
UNION ALL
SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD
),
target_user AS ( SELECT U.CMPNY_CD , U.SITE_CD , U.USER_CD FROM TB_USER U INNER JOIN node_tree NT ON U.CMPNY_CD = NT.CMPNY_CD AND U.SITE_CD = NT.SITE_CD AND U.NODE_CD = NT.NODE_CD WHERE U.CMPNY_CD = #{gvCmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
)
SELECT WP.USER_CD AS userCd , WP.WORK_YMD AS workYmd , SCH.FST_SCH_STR_TIME AS fstSchStrTime , SCH.FST_SCH_END_TIME AS fstSchEndTime , SCH.FST_SCH_BRK_MIN AS fstSchBrkMin , SCH.SEC_SCH_STR_TIME AS secSchStrTime , SCH.SEC_SCH_END_TIME AS secSchEndTime , SCH.SEC_SCH_BRK_MIN AS secSchBrkMin /* 그날 확정 부분연차(반차 '01' + 시간차 '02'~'04') 면제분 합계. 분할차감(PC-02/PC-05) 행은 첫 행에만 LEAVE_MINUTES 총량을 싣는 불변식이라 SUM = 총량. 종일('00')은 위 NOT EXISTS 로 이미 제외되어 여기 합산 대상이 아니다. */ , IFNULL(( SELECT SUM(L.LEAVE_MINUTES) FROM TB_USER_LEAVE_USE L WHERE L.CMPNY_CD = WP.CMPNY_CD AND L.USER_CD = WP.USER_CD AND L.LEAVE_STATUS = 'CONFIRMED' AND L.DEL_YN = 'N' AND L.START_DATE = WP.WORK_YMD AND L.USE_UNIT_TYPE <> '00' ), 0) AS leaveExemptMinutes FROM target_user U INNER JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = U.CMPNY_CD AND WP.SITE_CD = U.SITE_CD AND WP.USER_CD = U.USER_CD AND WP.WORK_YMD LIKE CONCAT(REPLACE(#{workYm}, '-', ''), '%')
/* 모수: WORK_PLAN_CD 가 스케줄코드(SCH_CD)인 근무일만 (연차셀 LEAVE_CD 분리). 종전 EXISTS 를 effective-dating INNER JOIN 으로 교체했다 — 모수 판정은 동일(매칭 실패 시 제외)하되 소정근로분 D 산출에 필요한 시각/휴게를 함께 내리기 위함이다(selectAttdSummaryRows 동일 서브쿼리). */ INNER JOIN ( SELECT E.CMPNY_CD , E.SITE_CD , E.SCH_CD , E.APPLY_DATE , E.FST_SCH_STR_TIME , E.FST_SCH_END_TIME , E.FST_SCH_BRK_MIN , E.SEC_SCH_STR_TIME , E.SEC_SCH_END_TIME , E.SEC_SCH_BRK_MIN FROM ( SELECT M.CMPNY_CD, M.SITE_CD, M.SCH_CD, M.APPLY_DATE , M.FST_SCH_STR_TIME, M.FST_SCH_END_TIME, M.FST_SCH_BRK_MIN , M.SEC_SCH_STR_TIME, M.SEC_SCH_END_TIME, M.SEC_SCH_BRK_MIN , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M UNION ALL SELECT H.CMPNY_CD, H.SITE_CD, H.SCH_CD, H.APPLY_DATE , H.FST_SCH_STR_TIME, H.FST_SCH_END_TIME, H.FST_SCH_BRK_MIN , H.SEC_SCH_STR_TIME, H.SEC_SCH_END_TIME, H.SEC_SCH_BRK_MIN , H.HIST_IDX FROM TB_SCH_MGMT_HIST H ) E WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ) SCH ON SCH.CMPNY_CD = WP.CMPNY_CD AND SCH.SITE_CD = WP.SITE_CD AND SCH.SCH_CD = WP.WORK_PLAN_CD AND SCH.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( SELECT M3.CMPNY_CD, M3.SITE_CD, M3.SCH_CD, M3.APPLY_DATE FROM TB_SCH_MGMT M3 UNION ALL SELECT H3.CMPNY_CD, H3.SITE_CD, H3.SCH_CD, H3.APPLY_DATE FROM TB_SCH_MGMT_HIST H3 ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD )
WHERE WP.WORK_PLAN_CD IS NOT NULL
/* 미래일 제외 (오늘 이후는 아직 출근 기회 미도래) */ AND WP.WORK_YMD <= DATE_FORMAT(CURDATE(), '%Y%m%d')
/* 연차일 제외 (TB_USER_LEAVE_USE 종일 확정 — Attd05 단일출처 술어 미러) */ AND NOT EXISTS ( SELECT 1 FROM TB_USER_LEAVE_USE L WHERE L.CMPNY_CD = WP.CMPNY_CD AND L.USER_CD = WP.USER_CD AND L.LEAVE_STATUS = 'CONFIRMED' AND L.DEL_YN = 'N' AND L.USE_UNIT_TYPE = '00' AND L.START_DATE <= WP.WORK_YMD AND L.END_DATE >= WP.WORK_YMD )
/* 휴일 제외 (HOLIDAY_TYPE 전체 — 법정/약정 구분 없이) */ AND NOT EXISTS ( SELECT 1 FROM TB_HOLIDAY HD WHERE HD.CMPNY_CD = WP.CMPNY_CD AND HD.USE_YN = 'Y' AND DATE_FORMAT(HD.HOLIDAY_YMD, '%Y%m%d') = WP.WORK_YMD )
/* 출근기록 존재일 제외 (차수 무관 — 어느 차수든 CHECK_IN 존재 시 출근일) */ AND NOT EXISTS ( SELECT 1 FROM TB_USER_ATTD_MGMT A WHERE A.CMPNY_CD = WP.CMPNY_CD AND A.SITE_CD = WP.SITE_CD AND A.USER_CD = WP.USER_CD AND A.WORK_YMD = WP.WORK_YMD AND A.DEL_YN = 'N' AND A.CHECK_IN_TIME IS NOT NULL AND A.CHECK_IN_TIME <> '' )
ORDER BY WP.USER_CD, WP.WORK_YMD
